import * as THREE from 'three';

export interface LightingConfig {
  ambientIntensity: number;
  hemiSkyColor: number;
  hemiGroundColor: number;
  hemiIntensity: number;
  sunIntensity: number;
  cameraFillIntensity: number;
  floodlightIntensity: number;
  floodlightDecay: number;
  roadRoughness: number;
  roadMetalness: number;
}

export const LIGHTING_CONFIG: LightingConfig = {
  ambientIntensity: 0.32,
  hemiSkyColor: 0xbfd4e6,
  hemiGroundColor: 0x6b5a45,
  hemiIntensity: 0.55,
  sunIntensity: 1.15,
  cameraFillIntensity: 0.45,
  floodlightIntensity: 2.4,
  floodlightDecay: 1.1,
  roadRoughness: 0.91,
  roadMetalness: 0.035,
};

export function applyRoadLightingOptimization(
  roadMat: THREE.MeshStandardMaterial,
  camera: THREE.Camera
): THREE.DirectionalLight {
  roadMat.roughness = THREE.MathUtils.clamp(LIGHTING_CONFIG.roadRoughness, 0.88, 0.94);
  roadMat.metalness = THREE.MathUtils.clamp(LIGHTING_CONFIG.roadMetalness, 0.02, 0.05);
  roadMat.envMapIntensity = 0.35;
  roadMat.needsUpdate = true;

  const cameraFill = new THREE.DirectionalLight(0xffffff, LIGHTING_CONFIG.cameraFillIntensity);
  cameraFill.name = 'CameraFillLight';
  cameraFill.castShadow = false;

  const target = new THREE.Object3D();
  target.position.set(0, 0, -1);
  cameraFill.target = target;

  camera.add(cameraFill);
  camera.add(target);

  cameraFill.position.set(0, 0.35, 0.6);

  return cameraFill;
}
